568	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
569	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
570		type pending struct {
571			id  seriesID
572			ref SeriesRef
573			ts  int64
574			val float64
575		}
576	
577		added := 0
578		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
579		seen := make(map[seriesID]map[int64]float64)
580		// 仅记录需要落盘的新增点；校验全部通过后才提交。
581		commits := make([]pending, 0, len(items))
582	
583		failAt := func(index int, msg string) *LineError {
584			return &LineError{Status: "error", Index: index, Error: msg}
585		}
586		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
587			return &LineError{
588				Status: "error",
589				Index:  index,
590				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
591					ref, ts, formatFloat(existing), formatFloat(submitted)),
592				Conflict: &Conflict{
593					// 标签必须复制：冲突结果是本次失败的独立记录，
594					// 调用方修改它不能改动已存序列的身份。
595					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
596					Timestamp: ts,
597					Existing:  existing,
598					Submitted: submitted,
599				},
600			}
601		}
602	
603		for i, item := range items {
604			pos := i + 1
605			p, err := parseSample(item)
606			if err != nil {
607				return nil, failAt(pos, err.Error())
608			}
609	
610			id := makeSeriesID(p.name, p.labels)
611			ref := SeriesRef{Name: p.name, Labels: p.labels}
612	
613			if byTS, ok := seen[id]; ok {
614				if old, ok := byTS[p.ts]; ok {
615					if old != p.value {
616						return nil, conflictAt(pos, ref, p.ts, old, p.value)
617					}
618					// 同批内重复出现且数值相同：重复，成功忽略。
619					continue
620				}
621			}
622			if sr, ok := s.series[id]; ok {
623				if old, ok := sr.points[p.ts]; ok {
624					if old != p.value {
625						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
626					}
627					// 与此前批次已写入的值相同：重复，成功忽略。
628					// seen 记录的是已存值 old 而不是本次提交的 p.value：
629					// 数值相等但表示不同（如已存 +0、本次提交 -0）时，
630					// 本批后续在同位置的冲突必须如实报告首次接受的已存值，
631					// 不能被这条被忽略的重复改写。
632					if seen[id] == nil {
633						seen[id] = map[int64]float64{}
634					}
635					seen[id][p.ts] = old
636					continue
637				}
638			}
639	
640			added++
641			if seen[id] == nil {
642				seen[id] = map[int64]float64{}
643			}
644			seen[id][p.ts] = p.value
645			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
646		}
647	
648		// 全部采样点合法且无冲突，原子提交本批新增点。
649		for _, c := range commits {
650			sr := s.series[c.id]
651			if sr == nil {
652				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
653				s.series[c.id] = sr
654			}
655			sr.points[c.ts] = c.val
656		}
657	
658		return s.snapshot(added, len(items)-added), nil
659	}
660	
661	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
662	func formatFloat(v float64) string {
663		return strconv.FormatFloat(v, 'g', -1, 64)
664	}
665	
666	type parsedQuery struct {
667		name   string
668		start  int64
669		end    int64
670		labels map[string]string
671	}
672	
673	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
674	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
675		q, err := parseQuery(raw)
676		if err != nil {
677			return nil, &LineError{Status: "error", Error: err.Error()}
678		}
679		if q.start > q.end {
680			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
681				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
682		}
683		return s.runQuery(q), nil
684	}
685	
686	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
687	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
688	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
689		var q parsedQuery
690		err := parseStrictObject(raw,
691			"each query must be a JSON object",
692			"unexpected content after the query object",
693			[]string{"op", "name", "start", "end"},
694			map[string]fieldReader{
695				"op": func(dec *json.Decoder) error {
696					t, err := dec.Token()
697					if err != nil {
698						return err
699					}
700					op, ok := t.(string)
701					if !ok {
702						return fmt.Errorf(`field "op" must be a string`)
703					}
704					if op != "query" {
705						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
706					}
707					return nil
708				},
709				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
710				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
711				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
712				"labels": func(dec *json.Decoder) error {
713					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
714				},
715			})
716		return q, err
717	}
718	
719	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
720	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
721	func labelsMatch(want, stored map[string]string) bool {
722		for k, v := range want {
723			got, ok := stored[k]
724			if !ok || got != v {
725				return false
726			}
727		}
728		return true
729	}
730	
731	// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
732	// 查询只返回每条序列的点数与均值，因此不借用写入快照的全量展示准备：既不整理
733	// 无关指标的序列，也不把区间内采样点按时间排成完整 Point 列表——单次遍历点表
734	// 只做计数与精确有理数求和（计数与均值都与点的排列次序无关）。
735	// 命中序列的相对次序仍与写入快照一致：仅对通过名称与标签筛选的序列套用同一套
736	// 排序约定（指标名字典序，再按标签键升序后的键值对逐对比较），排好的序列是
737	// 全量排序中的一个子序列；区间内没有点的序列不列出，不补零值条目。
738	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
739		matched := make([]organizedSeries, 0)
740		for _, sr := range s.series {
741			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
742				continue
743			}
744			// 标签必须复制：查询结果是当次操作的独立记录，
745			// 调用方修改结果标签不能改动已存序列的身份。
746			labels := cloneLabels(sr.ref.Labels)
747			matched = append(matched, organizedSeries{
748				sr:    sr,
749				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
750				pairs: sortedPairs(labels),
751			})
752		}
753		// 命中序列名称都相同，只需逐对比较排序后的标签；无标签（空前缀）排最前。
754		sort.Slice(matched, func(i, j int) bool {
755			return compareLabelPairs(matched[i].pairs, matched[j].pairs) < 0
756		})
757	
758		out := make([]QuerySeries, 0, len(matched))
759		for _, entry := range matched {
760			// 一次遍历直接统计：区间内点的个数与精确总和。不构造值切片、
761			// 不排序时间戳，避免为只返回 count/average 的查询承担采样明细展示。
762			// 求和在有理数上精确完成：与写入顺序、批次划分无关，正负大数抵消后的
763			// 小余量不会丢失，总和超出 float64 范围时均值仍然有限。
764			count := 0
765			sum := new(big.Rat)
766			r := new(big.Rat)
767			for ts, v := range entry.sr.points {
768				if ts < q.start || ts > q.end {
769					continue
770				}
771				count++
772				// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
773				sum.Add(sum, r.SetFloat64(v))
774			}
775			if count == 0 {
776				continue
777			}
778			sum.Quo(sum, r.SetInt64(int64(count)))
779			out = append(out, QuerySeries{
780				Name:   entry.ref.Name,
781				Labels: entry.ref.Labels,
782				Count:  count,
783				// 精确平均舍入到最近可表示 float64（正中取偶）；精确为零时返回 +0。
784				Average: ratToFloat64NearestEven(sum),
785			})
786		}
787		return &QueryResult{Status: "ok", Op: "query", Series: out}
788	}
789	
790	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
791	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
792	func ratToFloat64NearestEven(x *big.Rat) float64 {
793		if x.Sign() == 0 {
794			return 0
795		}
796		num := new(big.Int).Set(x.Num())
797		den := x.Denom()
798		neg := num.Sign() < 0
799		if neg {
800			num.Neg(num)
801		}
802	
803		// e 满足 2^e <= num/den < 2^(e+1)。
804		e := floorLog2Rat(num, den)
805		var m *big.Int
806		scale := 0
807		if e >= -1022 {
808			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
809			scale = e - 52
810			m = roundScaledRatio(num, den, scale)
811			if m.BitLen() == 54 {
812				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
813				m.Rsh(m, 1)
814				scale++
815			}
816		} else {
817			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
818			scale = -1074
819			m = roundScaledRatio(num, den, scale)
820		}
821		// m < 2^53，可以精确放入 int64 与 float64。
822		f := math.Ldexp(float64(m.Int64()), scale)
823		if neg {
824			return -f
825		}
826		return f
827	}
828	
829	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
830	func floorLog2Rat(num, den *big.Int) int {
831		k := num.BitLen() - den.BitLen()
832		var t big.Int
833		if k >= 0 {
834			t.Lsh(den, uint(k))
835			if num.Cmp(&t) >= 0 {
836				return k
837			}
838			return k - 1
839		}
840		t.Lsh(num, uint(-k))
841		if t.Cmp(den) >= 0 {
842			return k
843		}
844		return k - 1
845	}
846	
847	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
848	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
849		n := new(big.Int).Set(num)
850		d := new(big.Int).Set(den)
851		if scale >= 0 {
852			d.Lsh(d, uint(scale))
853		} else {
854			n.Lsh(n, uint(-scale))
855		}
856		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
857		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
858		case 1:
859			q.Add(q, big.NewInt(1))
860		case 0:
861			if q.Bit(0) == 1 {
862				q.Add(q, big.NewInt(1))
863			}
864		}
865		return q
866	}
867	
868	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
869	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
870	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
871	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
872	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
873	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
874	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
875	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
876	func (r SeriesRef) String() string {
877		var b strings.Builder
878		b.WriteString(identityText(r.Name))
879		b.WriteByte('{')
880		for i, p := range sortedPairs(r.Labels) {
881			if i > 0 {
882				b.WriteByte(',')
883			}
884			b.WriteString(identityText(p.Key))
885			b.WriteByte('=')
886			b.WriteString(identityText(p.Value))
887		}
888		b.WriteByte('}')
889		return b.String()
890	}
891	
892	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
893	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
894	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
895	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
896	// 因此渲染结果不会把内容字符误读为标签边界。
897	func identityText(s string) string {
898		if s == "" || s != strings.TrimSpace(s) {
899			return strconv.Quote(s)
900		}
901		for _, r := range s {
902			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
903				return strconv.Quote(s)
904			}
905		}
906		return s
907	}
908	
909	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
910	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
911	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
912	// 整理好的键值对，供排序比较直接复用。写入快照对全部已存序列整理；
913	// 区间查询只对名称与标签命中的序列整理同一份排序依据。
914	type organizedSeries struct {
915		sr    *storedSeries
916		ref   SeriesRef
917		pairs []labelPair
918	}
919	
920	// organizeSeries 是写入快照的全量数据整理：遍历全部已提交序列，
921	// 复制各自的序列身份，并按唯一的顺序约定排列——先按指标名字符串字典序，
922	// 再按标签键升序后的键值对逐对比较（先比键再比值，前一对相同才比下一对；
923	// 较短集合是完整前缀时排前，无标签序列因此排在最前）。标签值按字符串比较
924	// （"10" 在 "2" 之前）。每条序列的标签只在遍历时整理一次：排序后的键值对
925	// 随条目保留，sort 的反复比较直接复用同一份结果，不会因一条序列参与多次
926	// 比较而反复整理同一套标签。整理结果不复制采样点；采样点的完整选取与升序
927	// 排列由 allSeriesPoints 完成。只返回统计结果的区间查询不经过这里，
928	// 不会为无关指标与区间外采样点承担这套展示准备。
929	func (s *MetricStore) organizeSeries() []organizedSeries {
930		out := make([]organizedSeries, 0, len(s.series))
931		for _, sr := range s.series {
932			// 标签必须复制：成功结果是当次操作的独立记录，
933			// 调用方修改结果标签不能改动已存序列的身份。
934			labels := cloneLabels(sr.ref.Labels)
935			out = append(out, organizedSeries{
936				sr:    sr,
937				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
938				pairs: sortedPairs(labels),
939			})
940		}
941		sort.Slice(out, func(i, j int) bool {
942			if out[i].ref.Name != out[j].ref.Name {
943				return out[i].ref.Name < out[j].ref.Name
944			}
945			return compareLabelPairs(out[i].pairs, out[j].pairs) < 0
946		})
947		return out
948	}
949	
950	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，数值与
951	// 时间戳一一对应，供写入快照展示。返回的是新建切片与新建 Point，调用方对
952	// 采样点的修改不影响存储，也不影响此前或此后取得的其他成功结果。区间查询
953	// 不构造这样的明细列表，只在点表上计数与求和。
954	func allSeriesPoints(sr *storedSeries) []Point {
955		tsList := make([]int64, 0, len(sr.points))
956		for ts := range sr.points {
957			tsList = append(tsList, ts)
958		}
959		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
960		points := make([]Point, len(tsList))
961		for i, ts := range tsList {
962			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
963		}
964		return points
965	}
966	
967	// snapshot 生成按规范排序的全部序列视图：序列次序来自 organizeSeries，
968	// 点排列来自 allSeriesPoints，这是写入侧的全量展示准备；区间查询不经过
969	// 这套整理，只针对命中序列直接统计点数与精确均值。
970	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
971		organized := s.organizeSeries()
972		views := make([]SeriesView, 0, len(organized))
973		for _, os := range organized {
974			views = append(views, SeriesView{
975				Name:   os.ref.Name,
976				Labels: os.ref.Labels,
977				Points: allSeriesPoints(os.sr),
978			})
979		}
980		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
981	}
982

